import React, { useMemo, useState } from "react";
import "./Loan.css";

/* =========================================================
   BANK / LENDER DATA
========================================================= */

const lenders = [
  {
    name: "State Bank of India",
    short: "SBI",
    logo: "https://upload.wikimedia.org/wikipedia/commons/c/cc/State_Bank_of_India_logo.svg",
    type: "Public Sector Bank",
  },
  {
    name: "ICICI Bank",
    short: "ICICI",
    logo: "https://upload.wikimedia.org/wikipedia/commons/1/1f/ICICI_Bank_Logo.svg",
    type: "Private Bank",
  },
  {
    name: "HDFC Bank",
    short: "HDFC",
    logo: "https://upload.wikimedia.org/wikipedia/commons/2/28/HDFC_Bank_Logo.svg",
    type: "Private Bank",
  },
  {
    name: "Axis Bank",
    short: "AXIS",
    logo: "https://upload.wikimedia.org/wikipedia/commons/1/1b/Axis_Bank_logo.svg",
    type: "Private Bank",
  },
  {
    name: "Kotak Mahindra Bank",
    short: "KOTAK",
    logo: "https://upload.wikimedia.org/wikipedia/commons/4/4e/Kotak_Mahindra_Bank_logo.svg",
    type: "Private Bank",
  },
  {
    name: "Punjab National Bank",
    short: "PNB",
    logo: "https://upload.wikimedia.org/wikipedia/commons/1/1e/Punjab_National_Bank-Logo.svg",
    type: "Public Sector Bank",
  },
  {
    name: "Bank of Baroda",
    short: "BOB",
    logo: "https://upload.wikimedia.org/wikipedia/commons/5/5b/Bank_of_Baroda_logo.svg",
    type: "Public Sector Bank",
  },
  {
    name: "Canara Bank",
    short: "CANARA",
    logo: "https://upload.wikimedia.org/wikipedia/commons/2/2f/Canara_Bank_Logo.svg",
    type: "Public Sector Bank",
  },
  {
