/* =========================================================
   HELPERS
========================================================= */

const formatINR = (value) => {
  if (!Number.isFinite(value)) return "₹0";

  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(value);
};

const calculateEMI = (principal, annualRate, years) => {
  const monthlyRate = annualRate / 12 / 100;
  const months = years * 12;

  if (!principal || !annualRate || !years) return 0;

  const emi =
    (principal *
      monthlyRate *
      Math.pow(1 + monthlyRate, months)) /
    (Math.pow(1 + monthlyRate, months) - 1);

  return emi;
};

/* =========================================================
   LOAN PAGE
========================================================= */

function Loan() {
  const [loanAmount, setLoanAmount] = useState(2000000);
  const [interestRate, setInterestRate] = useState(8.5);
  const [tenure, setTenure] = useState(20);

  const [salary, setSalary] = useState(50000);
  const [existingEMI, setExistingEMI] = useState(0);

  const [activeLoanType, setActiveLoanType] = useState("Home Loan");

  const [form, setForm] = useState({
    name: "",
    phone: "",
    email: "",
    city: "",
    employment: "Salaried",
    income: "",
    loanAmount: "",
    loanType: "Home Loan",
    message: "",
  });

  const [submitted, setSubmitted] = useState(false);

  /* =======================================================
     EMI CALCULATION
  ======================================================= */

  const emi = useMemo(
    () => calculateEMI(loanAmount, interestRate, tenure),
    [loanAmount, interestRate, tenure]
  );

  const totalPayment = emi * tenure * 12;
  const totalInterest = Math.max(totalPayment - loanAmount, 0);

  /* =======================================================
     ELIGIBILITY ESTIMATION
  ======================================================= */

  const eligibility = useMemo(() => {
    const availableEMI = Math.max(
      salary * 0.5 - existingEMI,
      0
    );

    const monthlyRate = interestRate / 12 / 100;
    const months = tenure * 12;

    if (!availableEMI || !monthlyRate || !months) {
      return 0;
    }

    const eligible =
      (availableEMI *
        (Math.pow(1 + monthlyRate, months) - 1)) /
      (monthlyRate * Math.pow(1 + monthlyRate, months));

    return Math.max(eligible, 0);
  }, [salary, existingEMI, interestRate, tenure]);

  /* =======================================================
     FORM HANDLERS
  ======================================================= */

  const handleChange = (e) => {
    const { name, value } = e.target;

    setForm((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleApply = (e) => {
    e.preventDefault();

    if (!form.name || !form.phone) {
      alert("Please enter your name and mobile number.");
      return;
    }

    const lead = {
      ...form,
      source: "REHOUSE REALTORS Loan Page",
      createdAt: new Date().toISOString(),
    };

    try {
      const existing = JSON.parse(
        localStorage.getItem("rehouse_loan_leads") || "[]"
      );

      localStorage.setItem(
        "rehouse_loan_leads",
        JSON.stringify([...existing, lead])
      );
    } catch (error) {
      console.error("Loan lead storage error:", error);
    }

    window.dispatchEvent(
      new CustomEvent("rehouse-loan-enquiry", {
        detail: lead,
      })
    );

    window.dispatchEvent(
      new CustomEvent("rehouse-project-enquiry", {
        detail: `Loan Enquiry - ${form.loanType}`,
      })
    );

    setSubmitted(true);

    setTimeout(() => {
      setSubmitted(false);
    }, 6000);
  };

  const scrollToApply = () => {
    document
      .getElementById("loan-application")
      ?.scrollIntoView({
        behavior: "smooth",
      });
  };

