            <div className="loan-eyebrow">
              <span />
              REHOUSE REALTORS FINANCE
              <span />
            </div>

            <h1>
              Make Your
              <br />
              Property Dream
              <br />
              <em>Possible.</em>
            </h1>

            <p>
              Explore home loans, property finance and other eligible
              financing options with professional assistance from
              application to documentation.
            </p>

            <div className="loan-hero-buttons">
              <button
                type="button"
                className="loan-gold-button"
                onClick={scrollToApply}
              >
                Apply for Loan
                <span>↗</span>
              </button>

              <a
                href="#emi-calculator"
                className="loan-outline-button"
              >
                Calculate EMI
                <span>↓</span>
              </a>
            </div>

            <div className="loan-trust-row">
              <div>
                <strong>01</strong>
                <span>Eligibility Guidance</span>
              </div>

              <div>
                <strong>02</strong>
                <span>Document Assistance</span>
              </div>

              <div>
                <strong>03</strong>
                <span>Application Support</span>
              </div>
            </div>

          </div>

          <div className="loan-hero-card">

            <div className="loan-card-top">
              <span>LOAN ESTIMATE</span>
              <span className="loan-live-dot">
                ●
              </span>
            </div>

            <div className="loan-card-main">
              <small>Estimated Monthly EMI</small>

              <strong>
                {formatINR(emi)}
              </strong>

              <span>
                Based on {interestRate}% p.a. for {tenure} years
              </span>
            </div>

            <div className="loan-card-details">
              <div>
                <span>Loan Amount</span>
                <strong>{formatINR(loanAmount)}</strong>
              </div>

              <div>
                <span>Interest Rate</span>
                <strong>{interestRate}%</strong>
              </div>

              <div>
                <span>Tenure</span>
                <strong>{tenure} Years</strong>
              </div>
            </div>

            <button
              type="button"
              onClick={scrollToApply}
              className="loan-card-button"
            >
              Check Your Options
              <span>→</span>
            </button>

          </div>
        </div>
      </section>

