                        placeholder="Enter your name"
                        value={form.name}
                        onChange={handleChange}
                        required
                      />
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Mobile Number *
                      </label>

                      <input
                        type="tel"
                        name="phone"
                        placeholder="Enter mobile number"
                        maxLength="10"
                        value={form.phone}
                        onChange={handleChange}
                        required
                      />
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Email Address
                      </label>

                      <input
                        type="email"
                        name="email"
                        placeholder="Enter email address"
                        value={form.email}
                        onChange={handleChange}
                      />
                    </div>

                    <div className="loan-form-field">
                      <label>
                        City
                      </label>

                      <input
                        type="text"
                        name="city"
                        placeholder="Your city"
                        value={form.city}
                        onChange={handleChange}
                      />
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Employment Type
                      </label>

                      <select
                        name="employment"
                        value={form.employment}
                        onChange={handleChange}
                      >
                        <option value="Salaried">
                          Salaried
                        </option>

                        <option value="Self Employed">
                          Self Employed
                        </option>

                        <option value="Business">
                          Business
                        </option>

                        <option value="Professional">
                          Professional
                        </option>

                        <option value="Other">
                          Other
                        </option>
                      </select>
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Monthly Income
                      </label>

                      <input
                        type="number"
                        name="income"
                        placeholder="Approx. monthly income"
                        value={form.income}
                        onChange={handleChange}
                      />
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Loan Type
                      </label>

                      <select
                        name="loanType"
                        value={form.loanType}
                        onChange={handleChange}
                      >
                        {loanTypes.map((loan) => (
                          <option
                            key={loan.title}
                            value={loan.title}
                          >
                            {loan.title}
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="loan-form-field">
                      <label>
                        Approx. Loan Amount
                      </label>

                      <input
                        type="number"
                        name="loanAmount"
                        placeholder="e.g. 2500000"
                        value={form.loanAmount}
                        onChange={handleChange}
                      />
                    </div>

                  </div>

                  <div className="loan-form-field full-field">
                    <label>
                      Additional Requirement
                    </label>

                    <textarea
                      name="message"
                      placeholder="Tell us anything else about your requirement..."
                      value={form.message}
                      onChange={handleChange}
                      rows="4"
                    />
                  </div>

                  <button
                    type="submit"
                    className="loan-gold-button full"
                  >
                    Submit Loan Enquiry
                    <span>↗</span>
                  </button>

                  <p className="loan-form-disclaimer">
                    By submitting this form, you agree that REHOUSE
                    REALTORS may contact you regarding your enquiry.
                    Submission does not guarantee loan approval.
                  </p>

                </form>
              )}

            </div>

          </div>

        </div>

      </section>

      {/* =====================================================
          FAQ
      ===================================================== */}

      <section className="loan-faq-section">

        <div className="loan-container">

          <div className="loan-section-heading centered">

            <div className="loan-section-number">
              09 / FAQ
            </div>

            <h2>
              Frequently asked
              <br />
              <em>questions.</em>
            </h2>

          </div>

          <div className="loan-faq-grid">

            <details>
              <summary>
                What is a home loan?
                <span>+</span>
              </summary>

              <p>
                A home loan is financing provided by a lender for an
                eligible residential property purchase, construction
                or other permitted purpose, subject to the lender's
                terms and conditions.
              </p>
            </details>

            <details>
              <summary>
                Can I check my EMI before applying?
                <span>+</span>
              </summary>

              <p>
                Yes. You can use the EMI calculator above to get an
                indicative estimate based on loan amount, interest
                rate and tenure.
              </p>
            </details>

            <details>
              <summary>
                Does REHOUSE REALTORS approve the loan?
                <span>+</span>
              </summary>

              <p>
                No. Final eligibility, approval, interest rate,
                documentation and disbursement are determined by
                the respective lender.
              </p>
            </details>

            <details>
              <summary>
                Can self-employed applicants apply?
                <span>+</span>
              </summary>

              <p>
                Self-employed applicants may be eligible for
                applicable loan products depending on the lender's
                criteria and documentation requirements.
              </p>
            </details>

            <details>
              <summary>
                What documents are usually required?
                <span>+</span>
              </summary>

              <p>
                Requirements vary. Common documents can include
                identity proof, address proof, income documents,
                bank statements and property-related documents.
              </p>
            </details>

            <details>
              <summary>
                Does checking eligibility guarantee approval?
                <span>+</span>
              </summary>

              <p>
                No. Eligibility calculations on this page are
                indicative only. Final approval is subject to the
                lender's assessment and applicable policies.
              </p>
            </details>

          </div>

        </div>

      </section>

      {/* =====================================================
          TERMS & CONDITIONS
      ===================================================== */}

      <section className="loan-terms-section">

        <div className="loan-container">

          <div className="loan-section-number">
            10 / TERMS & CONDITIONS
          </div>

          <div className="loan-terms-content">

            <h2>
              Terms, conditions
              <br />
              & <em>disclaimer.</em>
            </h2>

            <div className="loan-terms-list">

              <div>
                <span>01</span>
                <p>
                  All loan calculators and eligibility figures shown
                  on this page are indicative and are not a guarantee
                  of loan approval or sanction.
                </p>
              </div>

              <div>
                <span>02</span>
                <p>
                  Interest rates, processing fees, tenure, loan-to-value
                  ratios, eligibility criteria and other charges may
                  vary by lender and applicant profile.
                </p>
              </div>

              <div>
                <span>03</span>
                <p>
                  The respective bank or financial institution is
                  solely responsible for final underwriting, approval,
                  sanction, documentation, disbursement and other
                  lending decisions.
                </p>
              </div>

              <div>
                <span>04</span>
                <p>
                  Displaying a bank or lender name/logo does not by
                  itself represent a partnership, endorsement,
                  authorization or guaranteed availability of any
                  specific loan product.
                </p>
              </div>

              <div>
                <span>05</span>
                <p>
                  Applicants should independently review the final
                  sanction letter, loan agreement, applicable fees,
                  interest rate, insurance requirements and other
                  lender terms before accepting a loan.
                </p>
              </div>

              <div>
                <span>06</span>
                <p>
                  REHOUSE REALTORS may facilitate communication and
                  provide general assistance but does not guarantee
                  approval, rate, tenure, amount or disbursement.
                </p>
              </div>

            </div>

          </div>

        </div>

      </section>

      {/* =====================================================
          FINAL CTA
      ===================================================== */}

      <section className="loan-final-cta">

        <div className="loan-final-background" />

        <div className="loan-final-content">

          <div className="loan-section-number light">
            REHOUSE REALTORS
          </div>

          <h2>
            Ready to explore
            <br />
            your <em>loan options?</em>
          </h2>

          <p>
            Start with an EMI calculation or submit your requirement.
            We will help you understand the next steps.
          </p>

          <button
            type="button"
            className="loan-gold-button"
            onClick={scrollToApply}
          >
            Start Your Loan Enquiry
            <span>↗</span>
          </button>

        </div>

      </section>

    </main>
  );
}

export default Loan;
